function LogoItem({ partner, wrapperClass, svgClass }) {
  return (
    <a
      id={`partner-${partner.id}`}
      href={partner.url}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={partner.label}
      title={partner.label}
      className={`group relative inline-flex items-center justify-center transition-all duration-300 hover:-translate-y-1 ${wrapperClass}`}
    >
      {/* SVG Wrapper with tight scaling and text color transitions */}
      <div className={`max-w-full flex items-center justify-center ${svgClass}`}>
        {partner.svg}
      </div>
    </a>
  );
}

export default function PartnerLogos({ lang = "tr" }) {
  const heading = lang === "en" ? "Partners & References" : "Ortaklar & Referanslar";
  const sub = lang === "en"
    ? "Organizations defining the frontier of science and exploration"
    : "Bilim ve keşfin sınırlarını belirleyen kuruluşlar";

  return (
    <section className="glass-nav transition-theme" style={{ paddingTop: "64px", paddingBottom: "64px", borderTop: "1px solid var(--border-color)" }}>
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Heading */}
        <div className="text-center mb-12">
          <p className="font-mono text-[10px] uppercase tracking-widest mb-2" style={{ color: "var(--foreground-muted)" }}>
            {heading}
          </p>
          <p className="text-sm" style={{ color: "var(--foreground-subtle)" }}>{sub}</p>
        </div>

        {/* TIER 1 - Largest Logos (oxypace, nasa, spacex, cern, spacecom) */}
        <div className="flex flex-wrap items-center justify-center gap-3 mb-4">
          {TIER1_PARTNERS.map((p) => (
            <LogoItem 
              key={p.id} 
              partner={p} 
              wrapperClass="w-[220px] h-[90px]" 
              svgClass="h-12 w-44" 
            />
          ))}
        </div>

        {/* TIER 2 - Medium Logos (natgeo, thenorthface, google, ibm, mit, popularscience, canon, gopro, redbull) */}
        <div className="flex flex-wrap items-center justify-center gap-3 mb-4">
          {TIER2_PARTNERS.map((p) => (
            <LogoItem 
              key={p.id} 
              partner={p} 
              wrapperClass="w-[170px] h-[76px]" 
              svgClass="h-9 w-32" 
            />
          ))}
        </div>

        {/* TIER 3 - Small Logos (esa, tesla, porsche, apple, nvidia, warnerbros, claude, patagonia, arcteryx, garmin) */}
        <div className="flex flex-wrap items-center justify-center gap-3">
          {TIER3_PARTNERS.map((p) => (
            <LogoItem 
              key={p.id} 
              partner={p} 
              wrapperClass="w-[140px] h-[64px]" 
              svgClass="h-7 w-24" 
            />
          ))}
        </div>
      </div>
    </section>
  );
}
